 private static NBTTagCompound input(int code){if(code==0)return null;NBTTagCompound tag=new NBTTagCompound(),child=new NBTTagCompound();switch(code){case 1:break;case 2:tag.setInteger("SegmentedSpeed",0);break;case 3:tag.setTag("SegmentedSettings",child);break;case 4:child.setInteger("Direction",3);tag.setTag("SegmentedSettings",child);break;case 5:child.setString("Layout","bad");tag.setTag("SegmentedSettings",child);break;case 6:tag.setString("SegmentedSettings","future");break;case 7:tag.setIntArray("RedstoneChannels",new int[]{-1});break;case 8:tag.setIntArray("RedstoneChannels",new int[]{31,32});break;case 9:tag.setInteger("RedstoneChannel",123);break;case 10:tag.setBoolean("SegmentedLocalRedstone",false);tag.setBoolean("SegmentedSignalOpens",false);break;case 11:tag.setInteger("SegmentedSpeed",100);break;case 12:tag.setBoolean("SegmentedConfigured",true);break;default:SegmentedDoorTile tile=new SegmentedDoorTile();tile.settings=new SegmentedDoorSettings(code%4,true,2,0,true,2,true,new DoorGlassAppearance(-1,2,3,2),2);tile.ticksPerSection=20;tile.localRedstone=false;tile.signalOpens=false;tile.setRedstoneChannels(ChannelList.of(64777,64778));tag=tile.itemSettings();}return tag;}
